In what follows, we illustrate the size of $\varkappa.$
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.45\textwidth]{b_1.png}\includegraphics[width=0.45\textwidth]{b_10.png}
    \caption{Graphs of the Riesz means $\varkappa$ for $b=1,$ and for $b=10,$ respectively, in the interval $[20.1,97]$.}
    \label{fig:region-cosh}
\end{figure}

Let us consider the Weyl eigenvalue counting formula $N:=N(\lambda)$ of the operator $H(\zeta).$
    One can use the analysis in \cite[Page 297]{Laptev2016} in order to deduce that
    \begin{equation}
        \frac{\varkappa(\lambda)}{\lambda}\leq  N(\lambda)\leq \frac{\varkappa((\tau+1)\lambda)}{\tau\lambda}\leq \frac{1}{\pi^2b^2}(1+\tau^{-1}) \log^2((1+\tau)\lambda),\,\quad \forall\tau>0.
    \end{equation}

The  main results in \cite{Laptev2016}, which describe the asymptotic behavior of the Riesz mean \( \sum_{j \ge 1} (\lambda - \lambda_j)_+ \), and also state the corresponding Weyl laws for the eigenvalue counting function \( N(\lambda) \) associated with these operators, prove that
\begin{equation} \label{W-zeta}
\lim_{\lambda \rightarrow \infty} \frac{N(\lambda)}{\log^2 \lambda} = \frac{1}{(\pi b)^2},
\end{equation}
for the operator \( H(\zeta) \), and
\begin{equation} \label{W-mn}
\lim_{\lambda \rightarrow \infty} \frac{N(\lambda)}{\log^2 \lambda} = \frac{c_{m,n}}{(2\pi b)^2}, \quad c_{m,n} = \frac{(m+n+1)^2}{2mn},
\end{equation}
for the operator \( H_{m,n} \). We remark that the proof in \cite{Laptev2016} follows ideas originally developed in \cite{Laptev1997}, where the Fourier transform is replaced by the coherent state transform. The techniques employed in \cite{Laptev2016} also draw inspiration from the derivation of the Berezin–Lieb inequality \cite{Berezin1972,Berezin1972b,Lieb1973}.

\label{main:remark}
      We start by considering the following upper and lower bounds for $\varkappa(\lambda)$, see \cite[Pages 294 and 296]{Laptev2016}, which are a consequence of the identity in \eqref{H-coherent},
\begin{align*}
\sum_{j\geq 1}(\lambda-\lambda_j)_+\leq I_1= 4{\iint}_{\mathbb{R}^+_0\times \mathbb{R}^+_0} \big(\lambda-2d_1\cosh(2\pi bk)- 2d_2\cosh(2\pi by)\big)_+d kd y, 
\end{align*} and 
\begin{align*}
\sum_{j\geq 1}(\lambda-\lambda_j)_+ 
&\geq I_2= 4 \iint_{\mathbb{R}^+_0\times \mathbb{R}^+_0}\left(\lambda-\frac{2}{d_1}\cosh(2\pi bk)-\frac{2}{d_2}\cosh(2\pi by)\right)_+d k d y. 
\end{align*} Observe the presence of the factor $4$ in the right hand side of these inequalities in view of the symmetry of the surface $z = \cosh(2\pi k) + \cosh(2\pi y).$
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.45\textwidth]{6.png}\includegraphics[width=0.40\textwidth]{9.png}
    \caption{Symmetry of the surface \( z = \cosh(2\pi k) + \cosh(2\pi y) \) in \( \mathbb{R}^3 \) on the domain \( \{(k, y):-10\leq k,y\leq 10\} \).}
    \label{fig:region-cosh:2}
\end{figure}
